import numpy as np
from gensim import matutils
from numpy import dot, array


# Symbolic constants to replace magic numbers
INFINITY = float('inf')
ONE = 1
ZERO = 0


class VectorUtil:
    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(matutils.unitvec(vector_1), matutils.unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        norm = np.linalg.norm(vector_1)
        all_norms = np.linalg.norm(vectors_all, axis=1)
        dot_products = dot(vectors_all, vector_1)
        return dot_products / (norm * all_norms)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        if not (len(vector_list_1) and len(vector_list_2)):
            raise ZeroDivisionError('At least one of the passed list is empty.')

        return dot(matutils.unitvec(VectorUtil._mean_vector(vector_list_1)),
                   matutils.unitvec(VectorUtil._mean_vector(vector_list_2)))

    @staticmethod
    def _mean_vector(vector_list):
        return array(vector_list).mean(axis=0)

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        index_2_key_map, count_list = VectorUtil._build_index_and_count(number_dict)
        return VectorUtil._compute_idf_weights(total_num, count_list, index_2_key_map)

    @staticmethod
    def _build_index_and_count(number_dict):
        index_2_key_map = {}
        count_list = []
        for index, (key, count) in enumerate(number_dict.items()):
            index_2_key_map[index] = key
            count_list.append(count)
        return index_2_key_map, count_list

    @staticmethod
    def _compute_idf_weights(total_num, count_list, index_2_key_map):
        a = np.array(count_list)
        # smooth, in case the divide by zero error
        a = np.log((total_num + ONE) / (a + ONE))
        return {key: w for index, (key, w) in enumerate(VectorUtil._zip_indexed(a, index_2_key_map))}

    @staticmethod
    def _zip_indexed(array_values, index_2_key_map):
        for index, value in enumerate(array_values):
            yield index_2_key_map[index], value
